import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Leave } from '../models/leave.model';

@Injectable({
  providedIn: 'root'
})
export class LeaveService {
  private apiUrl = 'http://localhost:5000/'; // It Connects to backend

  constructor(private http: HttpClient) {}

  applyLeave(leave: Leave): Observable<any> {
    return this.http.post(this.apiUrl, leave);
  }

  getLeaves(): Observable<Leave[]> {
    return this.http.get<Leave[]>(this.apiUrl);
  }

  updateLeaveStatus(id: number, status: string): Observable<any> {
    return this.http.put(`${this.apiUrl}/${id}`, status);
  }
}
